pub fn clip(a: Vec<i8>, min: i8, max: i8) -> Vec<i8> {
    // Pre-allocate result vector with the same capacity as input
    let mut result = Vec::with_capacity(a.len());

    // Clip each element and push into the result vector
    for &x in &a {
        let clipped = if x < min {
            min
        } else if x > max {
            max
        } else {
            x
        };
        result.push(clipped);
    }

    result
}

